using System;
using System.Collections.Generic;
using System.Data;

// Single Responsibility Principle: DatabaseRecordIterator handles iteration logic
public class DatabaseRecordIterator : IEnumerator<DatabaseRecord>
{
    private readonly List<DatabaseRecord> _records;
    private int _currentIndex = -1;

    public DatabaseRecordIterator(List<DatabaseRecord> records)
    {
        _records = records;
    }

    public bool MoveNext()
    {
        _currentIndex++;
        return _currentIndex < _records.Count;
    }

    public void Reset()
    {
        _currentIndex = -1;
    }

    public DatabaseRecord Current
    {
        get
        {
            if (_currentIndex < 0 || _currentIndex >= _records.Count)
            {
                throw new InvalidOperationException("Invalid current index");
            }
            return _records[_currentIndex];
        }
    }

    object IEnumerator.Current
    {
        get { return Current; }
    }

    public void Dispose()
    {
        // No resources to dispose in this example
    }
}

// Single Responsibility Principle: DatabaseRecord handles data
public class DatabaseRecord
{
    public int Id { get; set; }
    public string Name { get; set; }
    public DateTime Timestamp { get; set; }
}

// Example usage
class Program
{
    static void Main()
    {
        // Simulate fetching records from a database
        List<DatabaseRecord> records = new List<DatabaseRecord>
        {
            new DatabaseRecord { Id = 1, Name = "Record 1", Timestamp = DateTime.Now },
            new DatabaseRecord { Id = 2, Name = "Record 2", Timestamp = DateTime.Now },
            new DatabaseRecord { Id = 3, Name = "Record 3", Timestamp = DateTime.Now }
        };

        // Create an iterator
        DatabaseRecordIterator iterator = new DatabaseRecordIterator(records);

        // Traverse records
        while (iterator.MoveNext())
        {
            Console.WriteLine("Record: {0} - {1}", iterator.Current.Id, iterator.Current.Name);
        }
    }
}

